/** Shorten a string for realtime previews / log metadata (never for storage). */
export function truncate(value: string, maxLength: number): string {
  const normalized = value.replace(/\s+/g, ' ').trim();
  if (normalized.length <= maxLength) return normalized;
  return `${normalized.slice(0, Math.max(0, maxLength - 1))}\u2026`;
}

/**
 * Strip path components / control characters from a browser supplied filename.
 * The stored object key is generated by the file service; this only protects
 * the metadata we hand to it.
 */
export function sanitizeFileName(fileName: string | undefined, fallback = 'attachment'): string {
  const raw = (fileName ?? '').split(/[\\/]/).pop() ?? '';
  const cleaned = raw.replace(/[\u0000-\u001f\u007f]/g, '').trim();
  if (cleaned.length === 0) return fallback;
  return cleaned.length > 180 ? cleaned.slice(0, 180) : cleaned;
}
